async function reportsPage(){let today=new Date(),quarters=Array.from({length:20},(_,i)=>{let y=today.getFullYear()-2+Math.floor(i/4),m=1+3*(i%4);return `${y}-${String(m).padStart(2,'0')}-01`}),currentQuarter=`${today.getFullYear()}-${String(1+3*Math.floor(today.getMonth()/3)).padStart(2,'0')}-01`;content.innerHTML=`<div class="main-inner">${heading('Reports & exports','One source for management figures, quarterly sales lists and the familiar Excel workbook.',`<button id="reportExport" class="button button-dark">↓ Download full Excel master</button>`)}<div class="report-grid" style="margin-top:0"><div class="card panel"><div class="section-head"><h2>Quarterly contracts & warranties expiring</h2><span class="pill">Regional sales teams</span></div><p class="mini-note">Choose a quarter and sales manager. The list is generated automatically from current contracts.</p><div class="toolbar"><select id="salesQuarter" class="select">${quarters.map(k=>`<option value="${k}" ${k===currentQuarter?'selected':''}>${new Date(k).toLocaleString('en-GB',{month:'long',year:'numeric'})}</option>`).join('')}</select><select id="salesManager" class="select"><option>All</option>${meta.stats.sales_managers.map(m=>`<option>${esc(m)}</option>`).join('')}</select><button class="button button-outline" id="csvSales">↓ Current manager CSV</button><button class="button button-primary" id="allSales">↓ Reports for every manager</button></div><div id="salesCount" class="notice"></div><div id="salesAllSummary" class="mini-note"></div><div class="table-shell" id="salesTable"></div></div><div class="card panel"><h2>Weekly contract values</h2><p class="mini-note">Oldest to newest, with the latest entries at the bottom of the Excel register.</p><div class="toolbar"><select id="weeklyYear" class="select">${Array.from({length:Math.max(1,today.getFullYear()-2013)},(_,i)=>today.getFullYear()-i).map(y=>`<option value="${y}">${y}</option>`).join('')}</select><select id="weeklyMonth" class="select" aria-label="Filter by month"><option value="">All months</option>${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}">${new Date(2026,i,1).toLocaleString('en-GB',{month:'long'})}</option>`).join('')}</select><select id="weeklyWeek" class="select" aria-label="Filter by ISO week"><option value="">All weeks</option>${Array.from({length:53},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}">Week ${String(i+1).padStart(2,'0')}</option>`).join('')}</select><button class="button button-outline" id="weeklyExcel">↓ Excel</button><button class="button button-primary" id="newWeekly">+ Add value</button></div><div class="kpi" style="padding:13px 0;min-height:auto"><div class="kpi-label">Recorded weekly contract values</div><div class="kpi-value" id="weeklyTotal">—</div><div class="kpi-footer" id="weeklyCount"></div></div><div class="table-shell" id="weeklyTable"></div><p class="fine-print">These values are contract entries recorded by week, not necessarily cash receipts.</p></div></div>${servicePlannerPanel()}<div class="card panel" style="margin-top:17px"><div class="section-head"><h2>Excel master backup</h2><span class="pill">Original approved layout</span></div><p class="statement">The complete Maintenance Master export retains the eight familiar worksheets, their original headings, Excel tables, filters, site colours and historical records. Saved contract updates are patched into the existing template.</p><button class="button button-primary" id="exportLarge">↓ Export complete Maintenance Master (.xlsx)</button><p class="fine-print" id="excelHealth">Checking Excel export readiness…</p></div></div>`;$('#reportExport').onclick=downloadExcel;$('#weeklyExcel').onclick=downloadExcel;$('#newWeekly').onclick=()=>openLedgerEditor('weekly');$('#exportLarge').onclick=downloadExcel;$('#salesQuarter').onchange=()=>{loadSales();loadAllSalesSummary()};$('#salesManager').onchange=loadSales;$('#weeklyYear').onchange=loadWeekly;$('#weeklyMonth').onchange=loadWeekly;$('#weeklyWeek').onchange=loadWeekly;$('#allSales').onclick=downloadAllSales;$('#serviceFilter').onchange=loadServicePlanner;$('#serviceSearch').oninput=()=>{clearTimeout(window.plannerTimer);window.plannerTimer=setTimeout(loadServicePlanner,250)};$('#csvSales').onclick=exportSalesCSV;await Promise.all([loadSales(),loadWeekly(),loadServicePlanner(),loadAllSalesSummary()]);try{const readiness=await api('/api/export/preflight');let msg=readiness.template.ok?'Excel export checks passed. New records will automatically extend the workbook tables, filters and relevant dropdowns.':'Excel export needs attention: '+(readiness.template.failures||[]).slice(0,2).join('; ');$('#excelHealth').textContent=msg}catch(e){$('#excelHealth').textContent='Could not verify the Excel template: '+e.message}}

