 root.querySelectorAll('[data-remove-eq]').forEach(b=>b.onclick=async()=>{if(!confirm('Unlink this equipment from the contract?'))return;try{await api(`/api/contracts/${cid}/equipment/${b.dataset.removeEq}`,{method:'DELETE'});toast('Equipment unlinked');await renderContractEquipment(cid)}catch(e){toast(e.message)}});
