// V12: Sales-manager report bundle and source-linked maintenance-planner review.
function servicePlannerPanel(){return `<div class="card panel" style="margin-top:17px"><div class="section-head"><h2>Service planner – dates to review</h2><span class="pill">Imported planning evidence</span></div><p class="mini-note">Planner entries include 2025–2026 dates and historical/future planning notes. Nothing changes an active contract until approved.</p><div class="toolbar"><select class="select" id="serviceFilter"><option>All</option><option>Strong match</option><option>Review potential match</option><option>Review multiple matches</option><option>Unmatched</option></select><input class="input" id="serviceSearch" placeholder="Search customer or contract"></div><div id="plannerCount" class="notice"></div><div class="table-shell" id="plannerTable"></div></div>`}
async function downloadAllSales(){let start=$('#salesQuarter').value;window.location.href='/api/reports/sales/all-managers/download?'+qs({start});}
async function loadAllSalesSummary(){let start=$('#salesQuarter').value;let x=await api('/api/reports/sales/all-managers?'+qs({start}));$('#salesAllSummary').textContent=`One click generates ${x.managers.length} separately named manager files covering ${x.total} expiring agreements. The files can be emailed after review; the app does not send emails automatically.`}
async function loadServicePlanner(){let status=$('#serviceFilter')?.value||'All',q=$('#serviceSearch')?.value||'';let result=await api('/api/service-planner?'+qs({status,q,limit:75}));
 $('#plannerCount').textContent=`${result.summary['Strong match']||0} strong proposed matches; ${result.summary['Review potential match']||0} potential; ${result.summary['Review multiple matches']||0} ambiguous; ${result.summary['Unmatched']||0} unmatched. Showing ${result.items.length} of ${result.total} selected records.`;
 $('#plannerTable').innerHTML=`<div class="scroll-table"><table class="data-table"><thead><tr><th>Planner site</th><th>Contract</th><th>Last service</th><th>Matched contract</th><th>Result</th><th></th></tr></thead><tbody>${result.items.map(x=>`<tr><td title="${esc(x.customer)}">${esc(x.customer)}</td><td>${esc(x.contract_number)}</td><td>${esc(formatDate(x.last_service))}</td><td>${esc(x.matched_customer||'—')}</td><td>${esc(x.approval?'Approved':x.match_status)}</td><td class="action-cell">${x.match_status==='Strong match'&&x.last_service&&!x.approval?`<button data-approve-planner="${x.source_row}" data-target="${x.contract_id}">Review</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">No matching entries.</td></tr>'}</tbody></table></div><p class="fine-print">Monthly schedule cells and historic comments remain attached to the source entries. This preview does not prove that a future appointment has been completed.</p>`;
 $('#plannerTable').querySelectorAll('[data-approve-planner]').forEach(b=>b.onclick=()=>approvePlannerRow(Number(b.dataset.approvePlanner),Number(b.dataset.target),result.items.find(x=>x.source_row===Number(b.dataset.approvePlanner))));
}
async function approvePlannerRow(sourceRow,id,item){if(!item)return;
 let contract=await api('/api/contracts/'+id);let currentDate=contract.fields['Last service recorded']||'Not recorded';
 if(!confirm(`Planner: ${item.customer}\nMatched contract: ${contract.fields['Customer / site']}\nContract reference: ${contract.fields['Contract number']}\nPlanner last-service date: ${item.last_service}\nCurrent last-service date: ${currentDate}\n\nOnly approve if the planner date is genuinely a completed service and belongs to this contract.`))return;
 let overwrite_existing=Boolean(currentDate!=='Not recorded'&&currentDate!==item.last_service);
 if(overwrite_existing&&!confirm('Replace the existing last-service date? Its previous value will remain in the audit history.'))return;
 try{await api('/api/service-planner/'+sourceRow+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contract_id:id,expected_revision:contract.revision,confirm:true,overwrite_existing})});toast('Verified last-service date saved with source and audit trail.');loadServicePlanner()}
 catch(e){toast(e.message)}
}
async function renderSiteContact(id){const c=await api('/api/contracts/'+id+'/contact');let box=$('#siteContactPanel');if(!box)return;let name=current?.fields?.['Customer / site']||'';
 box.innerHTML=`<p class="mini-note">Use a public business source and confirm the contact details before saving. No details are invented automatically.</p><button class="button button-outline" id="searchContactWeb">↗ Search publicly listed site contacts</button><div class="edit-grid" style="margin-top:12px">${[['contact_name','Contact / department'],['phone','Business telephone'],['email','Business email'],['website','Website'],['source_url','Source website URL']].map(([k,title])=>`<div class="field"><label>${title}</label><input data-site-contact="${k}" value="${esc(c[k]||'')}"></div>`).join('')}</div><button class="button button-primary" id="saveSiteContact" style="margin-top:12px">Save verified public contact</button><p class="field-hint" style="margin-top:8px">${c.verified_at?'Last reviewed: '+esc(c.verified_at):'No verified contact data saved yet.'}</p>`;
 $('#searchContactWeb').onclick=()=>window.open('https://www.google.com/search?q='+encodeURIComponent(name+' '+(current.fields['County']||'')+' official website contact phone email'),'_blank','noopener,noreferrer');
 $('#saveSiteContact').onclick=async()=>{let payload={};box.querySelectorAll('[data-site-contact]').forEach(el=>payload[el.dataset.siteContact]=el.value.trim());try{await api('/api/contracts/'+id+'/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});toast('Public contact details saved with source');renderSiteContact(id)}catch(e){toast(e.message)}};
}
